function utf8_bytes(string $s): string {
    $b = '';
    for ($i = 0; $i < mb_strlen($s, 'UTF-8'); $i++) {
        $ch = mb_substr($s, $i, 1, 'UTF-8');
        $cp = mb_ord($ch, 'UTF-8');
        if ($cp < 0x80) {
            $b .= chr($cp);
        } elseif ($cp < 0x800) {
            $b .= chr(0xC0 | ($cp >> 6));
            $b .= chr(0x80 | ($cp & 0x3F));
        } elseif ($cp < 0x10000) {
            $b .= chr(0xE0 | ($cp >> 12));
            $b .= chr(0x80 | (($cp >> 6) & 0x3F));
            $b .= chr(0x80 | ($cp & 0x3F));
        }
    }
    return $b;
}

